const axios = require("axios");

// Получаем доступные поля
const referencesArray = $input.item.json.references || [];
const messageId = $input.item.json.message_id;
const email = $input.item.json.email_llm;
const sender = $input.item.json.sender || '';

// Формируем массив email-ов для проверки
let allEmailsToCheck = [];

// Добавляем email_llm если есть
if (email && email.trim() !== '') {
    allEmailsToCheck.push(email);
}

// Добавляем sender в массив, если он есть и не совпадает с email_llm
if (sender && sender.trim() !== '') {
    const senderLower = sender.toLowerCase().trim();
    const exists = allEmailsToCheck.some(e => e.toLowerCase() === senderLower);

    if (!exists) {
        allEmailsToCheck.push(sender);
        console.log(`Добавлен sender в список проверки: ${sender}`);
    }
}

console.log(`Всего email-ов для проверки: ${allEmailsToCheck.length}`);
console.log(`Всего references для проверки: ${referencesArray.length}`);

// Функция для проверки с указанными параметрами
async function checkHistory(params) {
  try {
    const response = await axios.post(
      "http://37.18.2.51:8082/v1/get_mailing_history_id",
      params,
      { headers: { "Content-Type": "application/json" } }
    );

    return {
      success: true,
      data: response.data,
      params: params
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      params: params
    };
  }
}

if (messageId && (referencesArray.length > 0 || allEmailsToCheck.length > 0)) {
  try {
    let foundHistoryId = 0;
    let foundData = null;
    let lastError = null;
    let matchedEmail = null;
    let matchedReference = null;

    // ЭТАП 1: Сначала перебираем все references без email
    if (referencesArray.length > 0) {
      console.log("Этап 1: Перебор references без email");

      for (const ref of referencesArray) {
        console.log(`Проверяем reference: ${ref} (без email)`);

        const params = { 
          message_id: messageId, 
          references_id: ref
          // email не указываем
        };

        const result = await checkHistory(params);

        if (result.success && result.data && result.data.message === true) {
          foundHistoryId = result.data.id_history || 0;
          foundData = result.data;
          matchedReference = ref;
          // Если нашли по reference, берем первый email из списка как matched_email
          matchedEmail = allEmailsToCheck.length > 0 ? allEmailsToCheck[0] : null;
          console.log(`Найден id_history ${foundHistoryId} по reference ${ref}`);
          break;
        } else if (result.success) {
          console.log(`Reference ${ref} не дал результата`);
        } else {
          console.log(`Ошибка при проверке reference ${ref}: ${result.error}`);
          lastError = result.error;
        }
      }
    }

    // ЭТАП 2: Если не нашли по references, пробуем по email-ам
    if (foundHistoryId === 0 && allEmailsToCheck.length > 0) {
      console.log("Этап 2: Перебор email-ов");

      for (const emailItem of allEmailsToCheck) {
        console.log(`Проверяем email: ${emailItem}`);

        const params = { 
          message_id: messageId, 
          references_id: referencesArray.length > 0 ? referencesArray[0] : '', 
          email: emailItem 
        };

        const result = await checkHistory(params);

        if (result.success && result.data && result.data.message === true) {
          foundHistoryId = result.data.id_history || 0;
          foundData = result.data;
          matchedEmail = emailItem;
          console.log(`Найден id_history ${foundHistoryId} для email ${emailItem}`);
          break;
        } else if (result.success) {
          console.log(`Email ${emailItem} не дал результата`);
        } else {
          console.log(`Ошибка при проверке ${emailItem}: ${result.error}`);
          lastError = result.error;
        }
      }
    }

    // Формируем результат
    return {
      json: {
        ...item.json,
        mailing_found: foundHistoryId > 0,
        id_history: foundHistoryId,
        matched_email: matchedEmail,
        matched_reference: matchedReference,
        exe_id: $execution.id,
        checked_emails: allEmailsToCheck,
        checked_references: referencesArray,
        search_stage: matchedReference ? 'by_reference' : (matchedEmail ? 'by_email' : 'none')
      }
    };

  } catch (error) {
    // Глобальная ошибка
    return {
      json: {
        ...item.json,
        mailing_found: false,
        id_history: 0,
        matched_email: null,
        matched_reference: null,
        mailing_error: error.message,
        exe_id: $execution.id,
        checked_emails: allEmailsToCheck,
        checked_references: referencesArray
      }
    };
  }

} else {
  // Если нет обязательных параметров
  return {
    json: {
      ...item.json,
      id_history: 0,
      matched_email: null,
      matched_reference: null,
      exe_id: $execution.id,
      mailing_skipped: true,
      mailing_reason: "No messageId or (references/emails)",
      checked_emails: allEmailsToCheck,
      checked_references: referencesArray
    }
  };
}

const rawResponse = $json.text ?? "";

// Извлечение JSON из ответа LLM
function extractJsonFromResponse(str) {
  if (!str || typeof str !== "string") return null;

  // JSON внутри Markdown
  const jsonRegex = /```json\s*([\s\S]*?)```/i;
  const match = str.match(jsonRegex);

  if (match && match[1]) {
    return match[1].trim();
  }

  // JSON-объект
  const objectRegex = /\{[\s\S]*\}/;
  const objectMatch = str.match(objectRegex);

  if (objectMatch) {
    return objectMatch[0].trim();
  }

  // JSON-массив
  const arrayRegex = /\[[\s\S]*\]/;
  const arrayMatch = str.match(arrayRegex);

  if (arrayMatch) {
    return arrayMatch[0].trim();
  }

  return null;
}

// Парсинг результата
try {
  const cleaned = extractJsonFromResponse(rawResponse);

  if (!cleaned) {
    throw new Error("Не найден JSON в ответе LLM");
  }

  const parsed = JSON.parse(cleaned);

  if (!parsed || typeof parsed !== "object") {
    throw new Error("Некорректная структура JSON");
  }

  return {
    json: {
      ...$json,
      status_query_llm: true,
      type_llm: parsed.type ?? null,
      email_llm: parsed.email ?? null,
      parse_error: null
    }
  };

} catch (error) {
  return {
    json: {
      ...$json,
      status_query_llm: false,
      type_llm: null,
      email_llm: null,
      parse_error: error.message
    }
  };
}

