function formatDateTimeInMoscow(date) {
  const optionsDate = {
    timeZone: 'Europe/Moscow',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  };

  const optionsTime = {
    timeZone: 'Europe/Moscow',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  };

  const formattedDate = new Intl.DateTimeFormat('ru-RU', optionsDate).format(date);
  const formattedTime = new Intl.DateTimeFormat('ru-RU', optionsTime).format(date);

  return { formattedDate, formattedTime };
}

const { formattedDate, formattedTime } = formatDateTimeInMoscow(dateObj);

return {
  json: {
    ...item.json,
